-------------------import-----------------------
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
local FishingMgr = import('Game.UI.Fishing.FishingMgr')
local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local cs_coroutine = require 'XLua.cs_coroutine'
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

-------------------Class------------------------
---@class RoleAnimService
local RoleAnimService = Class("RoleAnimService")

function RoleAnimService.new(from)
    local obj = RoleAnimService.New()
    obj.luaDialog = from
    obj.curRodId = nil
    for k, v in pairs(obj.luaDialog) do
        obj[k] = v
    end
    return obj
end

function RoleAnimService:UpdateInfo()
    local equipRodId = fishingComponent:GetCurEquipRodId(self.placeId)
    FishingMgr:GetInstance():ChangeRodModel(checkNumber(equipRodId))
end

function RoleAnimService:ForceIdle()
    FishingMgr:GetInstance():ForceIdle()
end

function RoleAnimService:ChangeRoleStatus(status)
    if status == self.currentRoleStatus then return end

    self.currentRoleStatus = status
    local instance = FishingMgr:GetInstance()
    instance:ChangeRoleStatus(status)

    if status == ConstantsFishing.RoleStatus.Idle then
    elseif status == ConstantsFishing.RoleStatus.Cast then
        CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_ready)
        FishingMgr:GetInstance():ForceIdle()
        FishingMgr:GetInstance():SetSwingidle(true)
    elseif status == ConstantsFishing.RoleStatus.Fishing then
    elseif status == ConstantsFishing.RoleStatus.FishEnd then
        FishingMgr:GetInstance():SetSwingidle(false)
    end
end

function RoleAnimService:OnUpdate()
    if self.currentRoleStatus == ConstantsFishing.RoleStatus.Idle then
        FishingMgr:GetInstance():OnUpdataIdle()
    elseif self.currentRoleStatus == ConstantsFishing.RoleStatus.Fishing then
        FishingMgr:GetInstance():OnUpdata()
    end
end

function RoleAnimService:PlayCastRodAnimation(type)
    if self.currentRoleStatus ~= ConstantsFishing.RoleStatus.Cast then
        return
    end

    FishingMgr:GetInstance():SetSwingPar(type)
    FishingMgr:GetInstance():SetPullPar(true)
end

function RoleAnimService:OverReqFailed()
    FishingMgr:GetInstance():SetFinishPar(41)
    cs_coroutine.yield_return(WaitForSeconds(2))
    self:ChangeRoleStatus(ConstantsFishing.RoleStatus.FishEnd)

    CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_stringless)
    FishingMgr:GetInstance():HideShuiHuaEffect()
    FishingMgr:GetInstance():SetLineRenderActive(false)

    self:ChangeRoleStatus(ConstantsFishing.RoleStatus.Idle)
end

return RoleAnimService